    /** Returns the layout of a format version, or null if it is not known. */
    static Map<String, String> get(final String setupId) {
        for (int i = 0; i < ROWS.length; i += 2) {
            if (!ROWS[i].equals(setupId)) continue;
            final Map<String, String> m = new HashMap<String, String>();
            for (final String kv : ROWS[i + 1].split("\\|")) {
                final int eq = kv.indexOf('=');
                m.put(kv.substring(0, eq), kv.substring(eq + 1));
            }
            return m;
        }
        return null;
    }

    /** Oldest and newest supported versions, for messages. */
    static String range() {
        return ROWS[0].replace("Inno Setup Setup Data ", "") + " to " + ROWS[ROWS.length - 2].replace("Inno Setup Setup Data ", "");
    }
